    "id": "chemistry-1788673840154-149-531",
    "questionText": "The heat of formation of ethene, C₂H₄ is 50 kJ mol⁻¹ and that of ethane, C₂H₆ is -82 kJ mol⁻¹. Calculate the heat evolved in the process: C₂H₄ + H₂ → C₂H₆ (JAMB 2019)",
