    "id": "chemistry-1788724932270-277-673",
    "questionText": "The table shows the compositions of the atmosphere of planet X: CO₂ = 4%, N₂ = 72%, O₂ = 24%. Which of these gases are present in higher percentages on earth? (JAMB 2022)",
